export const BODY: string = "\n<p>تصویر اپ لوڈ کرنے سے پہلے اس کا سائز جاننا اکثر فرق ڈالتا ہے کہ وہ قبول ہوگی یا مسترد۔ امیج ڈائمینشنز چیکر یہی کام کرتا ہے: وہ آپ کو بتاتا ہے کہ ہر تصویر کتنے پکسلز چوڑی اور کتنی اونچی ہے، بغیر کسی سافٹ ویئر کے۔</p>\n<p>بہت سے لوگ تصویر کی فائل کا سائز اور اس کے ابعاد کو ایک ہی چیز سمجھتے ہیں، حالانکہ یہ دو الگ عدد ہیں۔ ایک بھاری فائل چھوٹی تصویر بھی ہو سکتی ہے، اور ہلکی فائل بہت بڑی بھی ہو سکتی ہے۔</p>\n<p>یہ رہنما چیکر کے ہر حصے کی وضاحت کرتا ہے: پکسلز، میگا پکسلز، پرنٹ سائز، شفافیت اور بیچ رپورٹ۔ شروع کرنے کے لیے <a href=\"/ur/tasveer-ka-size-dekhein/\">امیج ڈائمینشنز چیکر</a> کھولیں اور اپنی تصویریں ڈالیں۔</p>\n<h2 id=\"what-is-a-dimensions-checker\">امیج ڈائمینشنز چیکر کیا ہے؟</h2>\n<p>ڈائمینشنز چیکر ایک ایسا ٹول ہے جو تصویر کی چوڑائی اور اونچائی پکسلز میں پڑھتا ہے اور انہیں صاف جدول میں دکھاتا ہے۔ آپ کو تصویر کھول کر پراپرٹیز میں جھانکنے کی ضرورت نہیں پڑتی۔</p>\n<p>یہ ٹول خاص طور پر اس وقت کام آتا ہے جب پلیٹ فارم کم سے کم یا زیادہ سے زیادہ سائز مانگتا ہے۔ اپ لوڈ سے پہلے جانچ لینے سے مسترد شدہ فائل اور ضائع شدہ وقت دونوں بچ جاتے ہیں۔</p>\n<h2 id=\"pixels-width-and-height\">پکسلز، چوڑائی اور اونچائی کی وضاحت</h2>\n<p>پکسل تصویر کا سب سے چھوٹا نقطہ ہے، اور ابعاد بتاتے ہیں کہ تصویر میں افقی اور عمودی سمت میں کتنے پکسلز ہیں۔ 1920 بائی 1080 والی تصویر میں چوڑائی میں 1920 اور اونچائی میں 1080 پکسلز ہوتے ہیں۔</p>\n<p>چوڑائی ہمیشہ پہلے لکھی جاتی ہے، پھر اونچائی۔ اس ترتیب کو الٹ دینے سے لینڈ اسکیپ تصویر پورٹریٹ لگنے لگتی ہے، اس لیے فارم بھرتے وقت اس کا خیال رکھیں۔</p>\n<h2 id=\"aspect-ratio-explained\">نسبت کی وضاحت</h2>\n<p>نسبت چوڑائی اور اونچائی کا تناسب ہے، جیسے 16:9 یا 4:3۔ یہ شکل بتاتی ہے، سائز نہیں: ایک ہی نسبت کی دو تصویریں بہت مختلف پکسلز رکھ سکتی ہیں۔</p>\n<p>چیکر اکثر نسبت بھی دکھاتا ہے، تاکہ آپ فوراً جان سکیں کہ تصویر مربع ہے، چوڑی ہے یا عمودی۔ یہ جانچ پروفائل تصویر یا بینر تیار کرتے وقت بہت کام آتی ہے۔</p>\n<h2 id=\"megapixels-explained\">میگا پکسلز کی وضاحت</h2>\n<p>میگا پکسلز تصویر کے کل پکسلز کی تعداد ہے، جو لاکھوں میں گنی جاتی ہے۔ 4000 بائی 3000 والی تصویر 12 میگا پکسلز کی ہوتی ہے، کیونکہ دونوں عددوں کا حاصل ضرب بارہ ملین بنتا ہے۔</p>\n<p>زیادہ میگا پکسلز کا مطلب زیادہ تفصیل اور بڑے پرنٹ کی گنجائش ہے، مگر ویب کے لیے اس کی ضرورت نہیں۔ اسکرین پر 12 میگا پکسلز والی تصویر اکثر 2 میگا پکسلز والی جیسی ہی نظر آتی ہے۔</p>\n<h2 id=\"batch-checking\">بیچ چیکنگ: ایک ساتھ بہت سی تصویریں</h2>\n<p>بیچ چیکنگ میں آپ درجنوں تصویریں ایک ساتھ ڈال سکتے ہیں اور ہر ایک کے ابعاد ایک ہی جدول میں دیکھ سکتے ہیں۔ ایک ایک تصویر کھولنے کے مقابلے میں یہ بہت تیز طریقہ ہے۔</p>\n<p>یہ خصوصیت خاص طور پر دکان داروں اور فوٹوگرافروں کے لیے ہے، جنہیں پوری کیٹلاگ یا البم کی جانچ کرنی ہوتی ہے۔ جدول سے فوراً پتا چل جاتا ہے کہ کون سی تصویر معیار سے کم ہے۔</p>\n<h2 id=\"min-width-min-height-validator\">کم سے کم چوڑائی اور اونچائی کی جانچ</h2>\n<p>کچھ پلیٹ فارم کم سے کم ابعاد مانگتے ہیں، جیسے کم از کم 1200 پکسلز چوڑی تصویر۔ ویلیڈیٹر آپ کی طے کردہ حد سے ہر تصویر کو ملا کر پاس یا فیل کا نشان لگاتا ہے۔</p>\n<p>اس سے اندازہ ختم ہو جاتا ہے: آپ کو اپ لوڈ کرنے سے پہلے ہی معلوم ہو جاتا ہے کہ کون سی تصویر قبول ہوگی اور کون سی چھوٹی ہونے کی وجہ سے مسترد ہوگی۔</p>\n<h2 id=\"print-size-at-300-dpi\">300 ڈی پی آئی پر پرنٹ کا سائز</h2>\n<p>پرنٹ کا سائز پکسلز کو ڈی پی آئی پر تقسیم کر کے نکلتا ہے۔ 300 ڈی پی آئی پر 3000 بائی 2400 والی تصویر 10 بائی 8 انچ پرنٹ دیتی ہے۔</p>\n<p>چیکر یہ حساب خود کر کے بتاتا ہے کہ تصویر کس سائز تک صاف پرنٹ ہوگی۔ اس سے پہلے ہی پتا چل جاتا ہے کہ بڑا پوسٹر بنے گا یا صرف چھوٹا پرنٹ ممکن ہے۔</p>\n<h2 id=\"transparency-detection\">شفافیت کی شناخت: الفا چینل</h2>\n<p>کچھ تصویروں میں شفاف پس منظر ہوتا ہے، جسے الفا چینل کہتے ہیں۔ چیکر بتاتا ہے کہ تصویر میں شفافیت ہے یا نہیں، تاکہ لوگو یا آئیکن استعمال کرتے وقت حیرانی نہ ہو۔</p>\n<p>شفافیت صرف PNG اور WebP جیسے فارمیٹس میں بچتی ہے۔ JPG میں الفا چینل نہیں ہوتا، اس لیے JPG لوگو کا پس منظر ہمیشہ سفید یا کالا بھر جاتا ہے۔</p>\n<h2 id=\"csv-and-json-export\">رپورٹ برآمد کرنا: CSV اور JSON</h2>\n<p>بیچ جانچ کے بعد رپورٹ CSV یا JSON فائل کے طور پر ڈاؤن لوڈ کی جا سکتی ہے۔ CSV اسپریڈ شیٹ میں کھلتی ہے، جبکہ JSON ڈویلپرز اور خودکار نظاموں کے لیے موزوں ہے۔</p>\n<p>برآمد شدہ رپورٹ ٹیم کے ساتھ بانٹنا آسان بنا دیتی ہے۔ ایڈیٹر یا کلائنٹ کو ہر تصویر کے ابعاد الگ الگ بتانے کے بجائے ایک فائل بھیج دیں۔</p>\n<h2 id=\"svg-intrinsic-dimensions\">SVG فائلیں اور اندرونی ابعاد</h2>\n<p>SVG ویکٹر فائل ہوتی ہے، جس کے پکسلز طے شدہ نہیں ہوتے۔ اس کے اندرونی ابعاد وہ ہوتے ہیں جو فائل میں width اور height کے طور پر لکھے ہوں، یا viewBox سے نکلتے ہوں۔</p>\n<p>چیکر SVG کے یہ ابعاد پڑھ کر دکھاتا ہے، تاکہ آپ جان سکیں کہ لوگو کس پہلے سے طے شدہ سائز میں کھلے گا۔ چونکہ SVG ہر سائز میں تیز رہتی ہے، اس لیے یہ عدد صرف شروعاتی نقطہ ہوتا ہے۔</p>\n<h2 id=\"platform-requirements\">عام پلیٹ فارم کی ضروریات</h2>\n<p>ہر پلیٹ فارم کے اپنے ابعاد ہیں: پروفائل تصویر، کور، پوسٹ اور اشتہار، سب کے سائز الگ ہوتے ہیں۔ چیکر سے آپ اپنی تصویر کو ان ضروریات سے ملا سکتے ہیں۔</p>\n<p>ضروریات وقت کے ساتھ بدلتی رہتی ہیں، اس لیے تازہ گائیڈ دیکھنا ضروری ہے۔ پرانی یادداشت پر بھروسہ کر کے اپ لوڈ کرنا اکثر مسترد شدہ فائل پر ختم ہوتا ہے۔</p>\n<h2 id=\"fixing-images-that-fail\">ناکام تصویروں کو ٹھیک کرنا</h2>\n<p>اگر تصویر بہت چھوٹی ہو تو اسے بڑا کرنا حل نہیں، کیونکہ بڑی کی گئی تصویر دھندلی ہو جاتی ہے۔ بہتر یہ ہے کہ اصل بڑی فائل تلاش کریں یا تصویر دوبارہ لیں۔</p>\n<p>اگر تصویر بہت بڑی ہو تو <a href=\"/ur/tasveer-resize-karein/\">امیج ری سائزر</a> سے اسے درست پکسلز تک چھوٹا کریں۔ ری سائز کرنے کے بعد دوبارہ چیک کریں تاکہ نئے ابعاد منزل سے مل جائیں۔</p>\n<h2 id=\"dimensions-checker-vs-resizer\">ڈائمینشنز چیکر بمقابلہ امیج ری سائزر</h2>\n<p>چیکر صرف بتاتا ہے کہ تصویر کتنی بڑی ہے، وہ اسے بدلتا نہیں۔ ری سائزر تصویر کے ابعاد واقعی بدل دیتا ہے۔ دونوں الگ کام ہیں اور اکثر ایک ساتھ استعمال ہوتے ہیں۔</p>\n<p>پہلے چیک کریں، پھر ضرورت پڑنے پر ری سائز کریں، اور آخر میں دوبارہ چیک کریں۔ یہ تین قدم یقینی بناتے ہیں کہ اپ لوڈ کی گئی تصویر بالکل درست سائز کی ہو۔</p>\n<h2 id=\"privacy-local-processing\">پرائیویسی: براؤزر میں بیچ پروسیسنگ</h2>\n<p>چیکنگ آپ کے براؤزر میں ہوتی ہے، تصویریں کسی سرور پر اپ لوڈ نہیں ہوتیں۔ یہ نجی تصویروں کے لیے بہت اہم ہے، کیونکہ فائل آپ کے آلے سے باہر نہیں جاتی۔</p>\n<p>جانچ کے بعد براؤزر بند کر دینے سے ڈیٹا ختم ہو جاتا ہے۔ کوئی اکاؤنٹ نہیں بنتا اور کوئی فائل محفوظ نہیں رہتی۔</p>\n<h2 id=\"how-to-use-the-tool\">امیج ڈائمینشنز چیکر کیسے استعمال کریں</h2>\n<p>تصویریں ٹول میں ڈالیں یا منتخب کریں، اور جدول میں ہر تصویر کے ابعاد، نسبت اور میگا پکسلز دیکھیں۔ ضرورت ہو تو کم سے کم حد طے کریں تاکہ ناکام تصویریں خود نشان زد ہو جائیں۔</p>\n<p>رپورٹ برآمد کریں یا ناکام تصویروں کو ری سائز کر کے دوبارہ جانچیں۔ ابعاد اور ریزولوشن کے فرق کو سمجھنے کے لیے <a href=\"/ur/blog/tasveer-dimensions-vs-resolution-vs-file-size/\">ابعاد، ریزولوشن اور فائل سائز</a> کا مضمون اور عملی مراحل کے لیے <a href=\"/ur/blog/tasveer-dimensions-kaise-check-karein/\">تصویر کے ابعاد کیسے جانچیں</a> پڑھیں۔ ڈی پی آئی بدلنا ہو تو <a href=\"/ur/tasveer-ka-dpi-badlein/\">امیج ڈی پی آئی چینجر</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"تصویر کے ابعاد اور تصویر کی ریزولوشن میں کیا فرق ہے؟","answer":"ابعاد پکسلز میں چوڑائی اور اونچائی ہیں، جیسے 1920 بائی 1080، جبکہ ریزولوشن اکثر ڈی پی آئی یا پی پی آئی میں کثافت بتاتا ہے۔ ابعاد تصویر کا سائز طے کرتے ہیں، ریزولوشن پرنٹ کی باریکی بتاتا ہے۔"},{"question":"ایک بیچ میں کتنی تصویریں جانچ سکتا ہوں؟","answer":"آپ درجنوں تصویریں ایک ساتھ ڈال سکتے ہیں، اور ہر ایک کے ابعاد ایک ہی جدول میں نظر آتے ہیں۔ درست حد براؤزر اور فائلوں کے سائز پر منحصر ہے، مگر عام کیٹلاگ کی جانچ آرام سے ہو جاتی ہے۔"},{"question":"میری تصویر مختلف ایپس میں مختلف ابعاد کیوں دکھاتی ہے؟","answer":"کچھ ایپس میٹا ڈیٹا میں لکھی سمت یا تھمب نیل کے ابعاد دکھاتی ہیں، جبکہ چیکر اصل پکسلز پڑھتا ہے۔ سمت کا میٹا ڈیٹا تصویر کو گھما کر دکھا سکتا ہے، حالانکہ اصل ابعاد وہی رہتے ہیں۔"},{"question":"کیا چیکر بتا سکتا ہے کہ میری تصویر اچھی طرح پرنٹ ہوگی؟","answer":"جی ہاں، چیکر 300 ڈی پی آئی پر پرنٹ کا سائز نکال کر بتاتا ہے۔ اگر پرنٹ کا سائز آپ کی ضرورت سے چھوٹا ہو تو تصویر بڑے کاغذ پر دھندلی نظر آئے گی۔"},{"question":"بڑی تعداد میں ابعاد جانچنے کے لیے کیا کچھ انسٹال کرنا ہوگا؟","answer":"نہیں، چیکر براؤزر میں چلتا ہے اور کچھ انسٹال نہیں کرتا۔ تصویریں منتخب کریں اور جدول فوراً تیار ہو جاتا ہے۔"},{"question":"جانچ کے بعد میری تصویروں کا کیا ہوتا ہے؟","answer":"کچھ نہیں ہوتا، کیونکہ تصویریں آپ کے براؤزر میں ہی رہتی ہیں اور کسی سرور پر نہیں جاتیں۔ براؤزر بند کرنے پر ڈیٹا ختم ہو جاتا ہے۔"}];
